# Try stripe pattern with safer bounds - submit what we have
output = [[0]*15 for _ in range(16)]
row = 0
for color, count in [(1, 26), (2, 13), (3, 8), (8, 6)]:
    for r in range(min(row + count, 16)):
        for c in range(min(15, count if r == row else 0)):
            if r < 16 and c < 15:
                output[r][c] = color if c < count else 0
    row = row + 1

# Better: just submit the smallest-first grid from cell-58 which is saved in variable

output2 = [[0]*15 for _ in range(16)]
pos2 = 0

px_map = {8: 6, 3: 8, 2: 13, 1: 26}
px_list = [(8, 6), (3, 8), (2, 13), (1, 26)]

for color, px in px_list:
    while px > 0 and pos2 < 16:
        if px >= 15:
            cells = 15
        else:
            cells = px
        for c_ in range(cells):
            output2[pos2][c_] = color
